function tt_openModalDialog(event){event.preventDefault();if(DataTable.Dom.select(event.target).is("i"))element=DataTable.Dom.select(event.target).parent();else element=DataTable.Dom.select(event.target);id=element.attr("id").substr(element.attr("id").lastIndexOf("-")+1);if(id.substring(0,4)=="wide"){DataTable.Dom.select("#modal_dialog_shell .modal-dialog").addClass("modal-wide");DataTable.Dom.select("#modal_dialog_shell .modal-dialog").removeClass("modal-email")}else if(id.substring(0,5)=="email"){DataTable.Dom.select("#modal_dialog_shell .modal-dialog").addClass("modal-email");
DataTable.Dom.select("#modal_dialog_shell .modal-dialog").removeClass("modal-wide")}else{DataTable.Dom.select("#modal_dialog_shell .modal-dialog").removeClass("modal-wide");DataTable.Dom.select("#modal_dialog_shell .modal-dialog").removeClass("modal-email")}var modalShell=DataTable.Dom.select("#modal_dialog_shell");var loadingLabel=element.attr("aria-label")||element.attr("title")||element.attr("data-bs-original-title");if(typeof loadingLabel!=="string"||loadingLabel.trim()==="")loadingLabel="Loading dialog";
modalShell.attrRemove("aria-labelledby").attr("aria-label",loadingLabel);DataTable.Dom.select("#modal_dialog").html('<div id="throb" style="padding-left:230px; padding-top:175px; height:275px;"></div>');var Throb=tt_throbber(100,20,1.8).appendTo(DataTable.Dom.select("#throb").get(0)).start();dialog=ossModal("#modal_dialog_shell");ossAjax({url:element.attr("href"),async:true,cache:false,type:"POST",timeout:1E4,success:function(data){DataTable.Dom.select("#modal_dialog").html(data);var modalTitle=modalShell.find(".modal-title").first();
var modalTitleId=modalTitle.attr("id");var modalTitleText=modalTitle.text();var modalTitleIdIsToken=typeof modalTitleId==="string"&&modalTitleId!==""&&!/[\t\n\f\r ]/.test(modalTitleId);var matchingIds=DataTable.Dom.select("[id]").filter(function(node){return node.id===modalTitleId}).length;if(modalTitle.length&&modalTitleIdIsToken&&modalTitleText.trim()!==""&&matchingIds===1)modalShell.attr("aria-labelledby",modalTitleId).attrRemove("aria-label");DataTable.Dom.select(".modal-body").scrollTop(0);DataTable.Dom.select("#modal_dialog_cancel").on("click",
function(){dialog.hide()})},error:ossAjaxErrorHandler})}
function ossAjaxErrorHandler(XMLHttpRequest,textStatus,errorThrown){if(DataTable.Dom.select("#modal_dialog_shell").isVisible())if(DataTable.Dom.select("#modal_dialog_save").length){DataTable.Dom.select("#modal_dialog_save").prop("disabled",false).removeClass("disabled");DataTable.Dom.select("#modal_dialog_cancel").prop("disabled",false).removeClass("disabled")}else if(dialog)dialog.hide();if(DataTable.Dom.select("canvas").length)DataTable.Dom.select("canvas").remove();if(DataTable.Dom.select(".vb-throbber").length)DataTable.Dom.select(".vb-throbber").remove();
ossAddMessage("An unexpected error occurred.","danger",true)}
function ossAddMessage(msg,type,handled){rand=Math.floor(Math.random()*1E6);msgbox='<div id="oss-message-'+rand+'" class="alert alert-'+type+' alert-dismissible fade show">                                <button type="button" class="btn-close" data-bs-dismiss="alert" aria-label="Close"></button>                                    '+msg+"</div>";if(DataTable.Dom.select(".modal-body").isVisible()&&handled)DataTable.Dom.select(".modal-body").prepend(msgbox);else if(DataTable.Dom.select(".page-header").length)DataTable.Dom.select(".page-header").each(function(el){el.insertAdjacentHTML("afterend",
msgbox)});else if(DataTable.Dom.select(".page-content").length)DataTable.Dom.select(".page-content").prepend(msgbox);else if(DataTable.Dom.select(".container").length)DataTable.Dom.select(".container").each(function(el){el.insertAdjacentHTML("beforebegin",msgbox)});else if(DataTable.Dom.select("#main").length)DataTable.Dom.select("#main").prepend(msgbox);bootstrap.Alert.getOrCreateInstance(document.getElementById("oss-message-"+rand))}
function ossJscriptFieldValidator(fieldName,email){if(DataTable.Dom.select("#"+fieldName).val()!="")if(email){if(ossValidateEmail(DataTable.Dom.select("#"+fieldName).val())){DataTable.Dom.select("#div-form-"+fieldName).removeClass("error");DataTable.Dom.select("#help-"+fieldName).html("")}}else{DataTable.Dom.select("#div-form-"+fieldName).removeClass("error");DataTable.Dom.select("#help-"+fieldName).html("")}}
function addPluginTab(title,id){if(id.substr(0,4)!="tab_")id="tab_"+id;var tab='<li><a data-bs-toggle="tab"';if(DataTable.Dom.select("#"+id).find(".error").length)tab+=' class="text-danger"';tab+=' href="#'+id+'">'+title+"</a></li>\n";DataTable.Dom.select("#plugin_tabs").show().append(tab)}function ossValidateEmail(email){var emailReg=/^([\w-\.]+@([\w-]+\.)+[\w-]{2,4})?$/;if(emailReg.test(email))return true;else return false}
function randPasword(len,id){DataTable.Dom.select("#"+id).val(randomPassword(len));DataTable.Dom.select("#"+id).trigger("blur")}
function vmDataTableLogAjaxError(api,technicalNote,message){var settings=api.settings()[0];var mode=DataTable.ext.sErrMode||DataTable.ext.errMode;var full="DataTables warning: table id="+api.table().node().id+" - "+message+". For more information about this error, please see "+"https://datatables.net/tn/"+technicalNote;var table=DataTable.Dom.select(api.table().node());var stopped=false;var event=table.trigger("dt-error.dt",true,[settings,technicalNote,message],{dt:settings.api,stopPropagation:function(){stopped=
true;Event.prototype.stopPropagation.call(this)},stopImmediatePropagation:function(){stopped=true;Event.prototype.stopImmediatePropagation.call(this)}},true)[0];if(!table.isAttached()&&!stopped)DataTable.Dom.select(document.body).trigger("dt-error.dt",true,[settings,technicalNote,message],{dt:settings.api});if(typeof mode==="function")mode(settings,technicalNote,full);else if(mode==="throw")throw new Error(full);else if(mode==="alert")alert(full)}
function vmDataTableServerData(source,minimum){return function(data,callback,settings){var api=new DataTable.Api(settings);var language=settings.language;var search=data.search&&data.search.value?String(data.search.value).replace(/^[ \t\n\r\0\x0B]+|[ \t\n\r\0\x0B]+$/g,""):"";var searchTerm=search.charAt(0)==="*"?search.slice(1).replace(/^[ \t\n\r\0\x0B]+/,""):search;var searchLength=searchTerm.replace(/[\uD800-\uDBFF][\uDC00-\uDFFF]/g,"_").length;if(searchLength>0&&searchLength<minimum){var originalZeroRecords=
language.zeroRecords;var originalEmptyTable=language.emptyTable;var hint="Enter at least "+minimum+" characters to search.";language.zeroRecords=hint;language.emptyTable=hint;try{callback({draw:data.draw,recordsTotal:0,recordsFiltered:0,data:[]})}finally{language.zeroRecords=originalZeroRecords;language.emptyTable=originalEmptyTable}return}return ossAjax({url:source,type:settings.serverMethod||"GET",dataType:"json",cache:false,data:data,success:callback,error:function(xhr,error){var event=DataTable.Dom.select(api.table().node()).trigger("xhr.dt",
true,[settings,null,xhr],{dt:settings.api},true)[0];try{if(!event.defaultPrevented)if(error==="parsererror")vmDataTableLogAjaxError(api,1,"Invalid JSON response");else if(xhr.readyState===4)vmDataTableLogAjaxError(api,7,"Ajax error")}finally{api.processing(false)}}})}}function vmDataTableApi(table){return new DataTable.Api(table)}DataTable.util.object.assignDeep(DataTable.defaults,{pagingType:"simple_numbers",language:{paginate:{previous:"&larr; Previous",next:"Next &rarr;"}},orderMulti:false});
DataTable.ext.pager.numbers_length=5;var ossConfirmedForms=new WeakSet;var ossPendingConfirmForms=new WeakSet;
DataTable.Dom.select(document).on("submit","form[data-confirm]",function(event){var message=DataTable.Dom.select(this).attr("data-confirm");if(typeof message!=="string"||message==="")return;if(ossConfirmedForms.has(this)){ossConfirmedForms.delete(this);return}event.preventDefault();event.stopImmediatePropagation();var form=this;if(ossPendingConfirmForms.has(form))return;ossPendingConfirmForms.add(form);var submitter=event.submitter;ossConfirm(message,function(accepted){ossPendingConfirmForms.delete(form);
if(!accepted)return;ossConfirmedForms.add(form);try{if(typeof form.requestSubmit==="function")if(submitter)form.requestSubmit(submitter);else form.requestSubmit();else HTMLFormElement.prototype.submit.call(form)}finally{ossConfirmedForms.delete(form)}})});
